const rows = (r: unknown): Array<Record<string, unknown>> => (Array.isArray(r) ? r : (r as { rows?: Array<Record<string, unknown>> }).rows ?? []);
if (!ctx.user || ctx.user.role !== "{{param.subscriber_role}}") return true;
if (String(row.status ?? "pending") !== "pending") return "A new subscription starts as pending until Stripe confirms it.";
if (row.stripe_subscription_id || row.stripe_customer_id || row.current_period_end) return "Only Stripe can confirm a subscription.";
const plan = rows(await ctx.db.query("select active from plan where id = $1", [row.plan_id]))[0];
return (plan && plan.active !== false) || "That plan isn't available.";

if (!ctx.old || !ctx.user || ctx.user.role !== "{{param.subscriber_role}}") return true;
for (const f of ["subscriber_id", "plan_id", "status", "stripe_session_id", "stripe_subscription_id", "stripe_customer_id", "current_period_end"]) {
  if (String(ctx.old[f] ?? "") !== String(row[f] ?? "")) return "Only Stripe can change a subscription. Use Manage billing.";
}
return String(row.sync ?? "idle") === "requested" || String(row.sync ?? "") === String(ctx.old.sync ?? "") || "Only Stripe can change a subscription.";

