const key = await ctx.secrets.get("STRIPE_SECRET_KEY");
if (!key) throw new Error("Payments aren't set up yet: connect Stripe or add STRIPE_SECRET_KEY in the project settings.");
if (!ctx.app.url.startsWith("http")) throw new Error("This app's address isn't known yet. Open it from the preview or publish it, then try again.");
const done = ctx.app.url + "/billing?checkout=done";
const back = ctx.app.url + "/billing";
const form = (pairs: Array<[string, string]>) => pairs.map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join("&");
if (!user) throw new Error("Sign in to choose a plan.");
const plan = await ctx.db.get("plan", String(input["plan_id"] ?? ""));
if (!plan || plan["active"] === false) throw new Error("That plan isn't available.");
const priceId = String(plan["stripe_price_id"] ?? "");
if (!/^price_[A-Za-z0-9]+$/.test(priceId) || priceId.includes("REPLACE")) throw new Error("That plan isn't linked to a Stripe price yet.");
const me = (await ctx.db.list("{{param.subscriber_role}}", { filter: { user_id: user.id }, limit: 1 }))[0];
if (!me) throw new Error("Your account isn't set up yet. Try again in a moment.");
const res = await ctx.http.fetch("https://api.stripe.com/v1/checkout/sessions", {
  method: "POST",
  headers: { authorization: `Bearer ${key}`, "content-type": "application/x-www-form-urlencoded" },
  body: form([["mode", "subscription"], ["line_items[0][price]", priceId], ["line_items[0][quantity]", "1"], ["success_url", done], ["cancel_url", back], ["client_reference_id", String(me["id"])], ["customer_email", user.email], ["subscription_data[metadata][plan_id]", String(plan["id"])]]),
});
const session = res.json<{ id?: string; url?: string; error?: { message?: string } }>();
if (!res.ok || !session?.id || !session.url) throw new Error(`Stripe couldn't start checkout: ${session?.error?.message ?? res.status}`);
const sub = await ctx.db.create("subscription", { subscriber_id: String(me["id"]), plan_id: String(plan["id"]), status: "pending", sync: "idle", stripe_session_id: session.id });
return { url: session.url, subscription_id: String(sub["id"]) };

type Obj = Record<string, unknown>;
const type = String(row["type"] ?? "");
const obj = ((row["data"] as { object?: Obj } | undefined)?.object ?? {}) as Obj;
const idOf = (v: unknown): string => (typeof v === "string" ? v : v && typeof v === "object" && typeof (v as Obj)["id"] === "string" ? String((v as Obj)["id"]) : "");
const when = (sec: unknown): string | null => (typeof sec === "number" && sec > 0 ? new Date(sec * 1000).toISOString() : null);
const statusOf = (s: string) => (s === "active" || s === "trialing" ? "active" : s === "past_due" || s === "unpaid" ? "past_due" : s === "canceled" || s === "incomplete_expired" ? "canceled" : "pending");
const findBy = async (field: string, value: string): Promise<Obj | null> => (value ? (await ctx.db.list("subscription", { filter: { [field]: value }, limit: 1 }))[0] ?? null : null);
if (type === "checkout.session.completed") {
  if (obj["mode"] !== "subscription") return;
  const sub = await findBy("stripe_session_id", idOf(obj["id"]));
  if (!sub) { ctx.log(`stripe: no subscription for checkout ${idOf(obj["id"])}`); return; }
  const paid = obj["payment_status"] === "paid" || obj["payment_status"] === "no_payment_required";
  await ctx.db.update("subscription", String(sub["id"]), { stripe_subscription_id: idOf(obj["subscription"]), stripe_customer_id: idOf(obj["customer"]), ...(paid ? { status: "active" } : {}) });
  ctx.log(`stripe: checkout ${idOf(obj["id"])} completed${paid ? ", subscription active" : ""}`);
  return;
}
// Invoices and subscription changes name the Stripe subscription.
const parent = (obj["parent"] as { subscription_details?: { subscription?: unknown } } | undefined)?.subscription_details?.subscription;
const subId = type.startsWith("invoice.") ? idOf(obj["subscription"]) || idOf(parent) : idOf(obj["id"]);
if (!subId) return;
const sub = await findBy("stripe_subscription_id", subId);
// Not linked yet (Stripe can send these before checkout.session.completed):
// fail the run so it is retried shortly.
if (!sub) throw new Error(`stripe: subscription ${subId} isn't linked to a checkout yet — retrying`);
const id = String(sub["id"]);
if (type === "invoice.paid") {
  const line = ((obj["lines"] as { data?: Array<{ period?: { end?: number } }> } | undefined)?.data ?? [])[0];
  await ctx.db.update("subscription", id, { status: "active", ...(when(line?.period?.end) ? { current_period_end: when(line?.period?.end) } : {}) });
} else if (type === "invoice.payment_failed") {
  await ctx.db.update("subscription", id, { status: "past_due" });
} else if (type === "customer.subscription.updated" || type === "customer.subscription.deleted") {
  const items = (obj["items"] as { data?: Array<{ current_period_end?: number }> } | undefined)?.data ?? [];
  const end = when(obj["current_period_end"]) ?? when(items[0]?.current_period_end);
  await ctx.db.update("subscription", id, { status: type.endsWith("deleted") ? "canceled" : statusOf(String(obj["status"] ?? "")), ...(end ? { current_period_end: end } : {}) });
}
ctx.log(`stripe: ${type} applied to subscription ${id}`);

const key = await ctx.secrets.get("STRIPE_SECRET_KEY");
if (!key) throw new Error("Payments aren't set up yet.");
const id = String(input["subscription_id"] ?? "");
const sub = await ctx.db.get("subscription", id);
if (!sub) throw new Error("That subscription isn't yours or doesn't exist.");
const get = async <T,>(path: string): Promise<T | null> => {
  const res = await ctx.http.fetch(`https://api.stripe.com/v1/${path}`, { headers: { authorization: `Bearer ${key}` } });
  return res.ok ? res.json<T>() : null;
};
let subId = String(sub["stripe_subscription_id"] ?? "");
let customer = String(sub["stripe_customer_id"] ?? "");
if (!subId) {
  const session = await get<{ subscription?: string | null; customer?: string | null }>(`checkout/sessions/${encodeURIComponent(String(sub["stripe_session_id"] ?? ""))}`);
  if (!session?.subscription) return { status: String(sub["status"]) };
  subId = session.subscription;
  customer = session.customer ?? "";
}
const s = await get<{ status?: string; current_period_end?: number; items?: { data?: Array<{ current_period_end?: number }> } }>(`subscriptions/${encodeURIComponent(subId)}`);
if (!s?.status) return { status: String(sub["status"]) };
const status = s.status === "active" || s.status === "trialing" ? "active" : s.status === "past_due" || s.status === "unpaid" ? "past_due" : s.status === "canceled" || s.status === "incomplete_expired" ? "canceled" : "pending";
const end = s.current_period_end ?? s.items?.data?.[0]?.current_period_end;
await ctx.vars.set(`stripe-subscription:${id}`, { status, subId, customer, periodEnd: end ? new Date(end * 1000).toISOString() : null });
await ctx.db.update("subscription", id, { sync: "requested" });
return { status };

const key = `stripe-subscription:${String(row["id"])}`;
const v = await ctx.vars.get(key);
const s = (v && typeof v === "object" ? v : {}) as Record<string, unknown>;
const patch: Record<string, unknown> = { sync: "idle" };
if (typeof s["status"] === "string") {
  patch["status"] = s["status"];
  patch["stripe_subscription_id"] = String(s["subId"] ?? "");
  patch["stripe_customer_id"] = String(s["customer"] ?? "");
  patch["current_period_end"] = s["periodEnd"] ?? null;
}
await ctx.db.update("subscription", String(row["id"]), patch);
await ctx.vars.set(key, null);

const key = await ctx.secrets.get("STRIPE_SECRET_KEY");
if (!key) throw new Error("Payments aren't set up yet: connect Stripe or add STRIPE_SECRET_KEY in the project settings.");
if (!ctx.app.url.startsWith("http")) throw new Error("This app's address isn't known yet. Open it from the preview or publish it, then try again.");
const back = ctx.app.url + "/billing";
const form = (pairs: Array<[string, string]>) => pairs.map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join("&");
const sub = await ctx.db.get("subscription", String(input["subscription_id"] ?? ""));
const customer = sub ? String(sub["stripe_customer_id"] ?? "") : "";
if (!customer) throw new Error("There's no billing account for this subscription yet.");
const res = await ctx.http.fetch("https://api.stripe.com/v1/billing_portal/sessions", {
  method: "POST",
  headers: { authorization: `Bearer ${key}`, "content-type": "application/x-www-form-urlencoded" },
  body: form([["customer", customer], ["return_url", back]]),
});
const portal = res.json<{ url?: string; error?: { message?: string } }>();
if (!res.ok || !portal?.url) throw new Error(`Stripe couldn't open billing settings: ${portal?.error?.message ?? res.status}`);
return { url: portal.url };
